/* v4: full-screen portrait (9:16) startup splash, every launch, 7 seconds */
#startupSplash{position:fixed;inset:0;width:100vw;height:100dvh;z-index:100000;overflow:hidden;padding:0;margin:0;background:#030b16;transition:opacity .48s ease,visibility .48s ease}
#startupSplash.is-leaving{opacity:0;visibility:hidden;pointer-events:none}
#startupSplash .splash-backdrop{position:absolute;inset:-30px;background-image:var(--splash-bg);background-size:cover;background-position:center;filter:blur(22px) brightness(.55) saturate(1.15)}
#startupSplash .splash-poster{position:absolute;left:0;top:0;width:100%;height:100%;display:block;object-fit:contain;object-position:center;border:0;border-radius:0;animation:splashFade .6s ease both;
 -webkit-mask-image:linear-gradient(180deg,transparent 0,#000 7%,#000 93%,transparent 100%);mask-image:linear-gradient(180deg,transparent 0,#000 7%,#000 93%,transparent 100%)}
/* phones close to 9:16: cover the whole screen edge to edge (head, flag, dome and text stay inside the safe crop) */
@media(min-aspect-ratio:13/25) and (max-aspect-ratio:5/8){#startupSplash .splash-poster{object-fit:cover;object-position:50% 50%;-webkit-mask-image:none;mask-image:none}}
/* tall narrow phones (taller than 13:25): fit the width so no text is clipped; top/bottom blend into the matching deep-navy sky */
@media(max-aspect-ratio:13/25){#startupSplash .splash-backdrop{filter:blur(30px) brightness(.22) saturate(1.2)}#startupSplash .splash-poster{-webkit-mask-image:linear-gradient(180deg,transparent 0,#000 14%,#000 86%,transparent 100%);mask-image:linear-gradient(180deg,transparent 0,#000 14%,#000 86%,transparent 100%)}}
/* wide screens (tablet / desktop): portrait poster centered, sides blend into blurred sky of the same image */
@media(min-aspect-ratio:5/8){#startupSplash .splash-poster{-webkit-mask-image:linear-gradient(90deg,transparent 0,#000 9%,#000 91%,transparent 100%);mask-image:linear-gradient(90deg,transparent 0,#000 9%,#000 91%,transparent 100%)}}
#startupSplash .splash-wide{display:none;position:absolute;left:0;top:0;width:100%;height:100%;object-fit:cover;object-position:50% 50%;border:0;animation:splashFade .6s ease both}
/* screens a little wider than 9:16 (browser bars, small phones, tablets): use the side-extended poster so it still touches both screen edges with nothing cropped from the character, text or logo */
@media(min-aspect-ratio:9/16) and (max-aspect-ratio:81/100){#startupSplash .splash-wide{display:block}#startupSplash .splash-poster{display:none}}
/* v8 splash light-bar: sits exactly on the glowing line of the poster (frame = poster coordinates), same 7s linear timeline as before */
#startupSplash .splash-timer{position:absolute;left:10%;right:10%;top:84.19%;height:3px;margin-top:-1.5px;border-radius:99px;background:linear-gradient(90deg,rgba(90,180,255,0),rgba(120,205,255,.34) 12%,rgba(120,205,255,.34) 88%,rgba(90,180,255,0));overflow:visible;z-index:4;pointer-events:none}
#startupSplash .splash-timer::before{content:"";position:absolute;left:2%;right:2%;top:50%;height:30px;margin-top:-15px;background:linear-gradient(90deg,rgba(55,140,255,0) 0,rgba(55,140,255,.24) 14%,rgba(55,140,255,.24) 86%,rgba(55,140,255,0) 100%);-webkit-mask-image:linear-gradient(180deg,transparent 0,#000 50%,transparent 100%);mask-image:linear-gradient(180deg,transparent 0,#000 50%,transparent 100%);filter:blur(5px);opacity:.95}
#startupSplash .splash-timer span{position:absolute;left:0;top:0;bottom:0;display:block;height:100%;width:0;border-radius:99px;background:linear-gradient(100deg,transparent 34%,rgba(167,221,245,.95) 50%,transparent 66%) -140px 0/140px 100% no-repeat,linear-gradient(90deg,rgba(40,120,255,0) 0,#2b7dff 14%,#4fb8ff 60%,#d8f6ff 100%);box-shadow:0 0 5px rgba(150,220,255,.95),0 0 13px rgba(60,160,255,.8),0 0 28px rgba(35,105,255,.5),0 6px 16px rgba(255,70,120,.14);animation:splashProgress 7s linear forwards,spBarFlow 1.25s linear infinite}
#startupSplash .splash-timer span::after{content:"";position:absolute;right:-10px;top:50%;width:20px;height:20px;margin-top:-10px;border-radius:50%;background:radial-gradient(circle,#DCE8F2 0,#c8f2ff 20%,rgba(90,195,255,.8) 42%,rgba(255,90,135,.2) 66%,transparent 72%);animation:spBarHead .833s cubic-bezier(.3,.1,.3,1) infinite;will-change:transform,opacity}
@keyframes spBarFlow{from{background-position:-140px 0,0 0}to{background-position:460px 0,0 0}}
@keyframes spBarHead{0%,62%,100%{transform:scale(1);opacity:.92}9%{transform:scale(.82);opacity:1}21%{transform:scale(1.55);opacity:1}33%{transform:scale(1.05)}45%{transform:scale(1.25);opacity:.98}}
@keyframes splashProgress{to{width:100%}}@keyframes splashFade{from{opacity:0;transform:scale(1.02)}to{opacity:1;transform:none}}
@media(prefers-reduced-motion:reduce){#startupSplash,#startupSplash .splash-poster{transition:none!important;animation:none!important}#startupSplash .splash-timer span{animation:none;width:100%}#startupSplash .splash-timer span::after{animation:none}}
