/* v4.2: live ECG monitor on the final welcome screen: realistic P-QRS-T beat, scrolling trace, synced thump + phone vibration */
.live-ecg{position:relative;height:150px;margin:14px 0 10px;border-radius:20px;overflow:hidden;border:1px solid rgba(94,182,255,.22);background:
 linear-gradient(rgba(94,182,255,.07) 1px,transparent 1px) 0 0/100% 25px,linear-gradient(90deg,rgba(94,182,255,.07) 1px,transparent 1px) 0 0/25px 100%,radial-gradient(ellipse at 50% 50%,#0b1f24,#071014);box-shadow:inset 0 0 40px rgba(0,0,0,.5)}
