/* v5.16 articulated Canvas mascot / stairs — replaces legacy hop-image styling */
.gx{--d:12px;position:relative;height:360px;margin:6px 0 4px;perspective:900px}
.gx-glow{position:absolute;inset:0;background:radial-gradient(ellipse at 55% 92%,rgba(47,123,255,.34),transparent 62%);pointer-events:none}
.gx-floor{position:absolute;left:-6px;right:-6px;bottom:-7px;height:26px;border-radius:50%;background:radial-gradient(ellipse at 50% 40%,rgba(60,140,255,.28),rgba(10,26,70,.0) 70%);pointer-events:none;z-index:0}
.gx-steps{position:absolute;inset:0;z-index:1}
.gx-step{position:absolute;bottom:0;padding:0;border:0;background:none;cursor:pointer;color:#cfe4ff;font:inherit;-webkit-tap-highlight-color:transparent}
.gx-face{position:absolute;inset:0;border-radius:3px 0 0 0;background:linear-gradient(180deg,#1b3f94 0%,#12307a 38%,#0a1c4a 100%);border:1px solid rgba(110,185,255,.38);border-bottom:0;box-shadow:inset 0 1px 0 rgba(170,215,255,.4),inset 0 -26px 24px -14px rgba(0,8,30,.55),0 0 16px rgba(47,123,255,.2);transition:background .4s,box-shadow .4s,border-color .4s}
.gx-face::after{content:"";position:absolute;left:0;right:0;top:0;height:38%;background:linear-gradient(180deg,rgba(167,221,245,.11),transparent);pointer-events:none}
.gx-tread{position:absolute;left:0;right:calc(var(--d)*-1);top:calc(var(--d)*-1);height:var(--d);clip-path:polygon(0 100%,var(--d) 0,100% 0,calc(100% - var(--d)) 100%);background:linear-gradient(90deg,#6fb4ff,#3e86ee);box-shadow:0 0 12px rgba(94,182,255,.5);transition:background .4s}
.gx-side{position:absolute;top:calc(var(--d)*-1);bottom:0;right:calc(var(--d)*-1);width:var(--d);clip-path:polygon(0 var(--d),100% 0,100% calc(100% - var(--d)),0 100%);background:linear-gradient(180deg,#0b2260,#050f2c);display:none}
.gx-step.last .gx-side{display:block}
.gx-num{position:absolute;left:0;right:0;top:12px;text-align:center;line-height:1;pointer-events:none;text-shadow:0 0 10px rgba(110,190,255,.8)}
.gx-num small{display:block;font-size:7.5px;letter-spacing:.16em;font-weight:800;color:#8fbfff;margin-bottom:3px}
.gx-num b{display:block;font-size:20px;font-weight:900;color:#e9f3ff}
.gx-step.passed .gx-face{border-color:rgba(130,200,255,.7);box-shadow:inset 0 1px 0 rgba(170,215,255,.45),inset 0 -26px 24px -14px rgba(0,8,30,.5),0 0 16px rgba(47,123,255,.4)}
.gx-step.on .gx-face{background:linear-gradient(180deg,#4fa4ff 0%,#2565e0 40%,#123a9e 100%);border-color:#b9deff;box-shadow:inset 0 1px 0 #d6ecff,0 0 26px rgba(80,160,255,.75)}
.gx-step.on .gx-tread{background:linear-gradient(90deg,#c4e4ff,#7fbcff)}
.gx-step.on .gx-num b{color:#DCE8F2}
.gx-step.pulse .gx-face{animation:gxGlow .7s ease}
@keyframes gxGlow{0%{filter:brightness(1.9)}100%{filter:none}}
.gx-actor{position:absolute;inset:0;z-index:5;pointer-events:none}
