.gx-fx-halo{z-index:3;background:radial-gradient(circle,rgba(90,170,255,.30),rgba(47,123,255,.12) 45%,transparent 70%);opacity:0;animation:gxFxHalo 1.9s ease-out forwards}
.gx-fx-ring{z-index:2;border:1.5px solid rgba(120,195,255,.85);box-shadow:0 0 10px rgba(80,160,255,.7);opacity:0;animation:gxFxRing 1.3s ease-out forwards}
.gx-fx-ring.r2{animation-delay:.28s}
