.h7-row .h7-rw{color:#a9c3ee;font-size:12.5px;white-space:nowrap}
.h7-row .h7-rc{width:16px;height:16px;color:#cfe0ff;flex:none}
.h7-none{margin:2px 6px 8px;color:var(--h7-mut);font-size:13.5px;line-height:1.45}
.h7 button:focus-visible,.h7 [role=button]:focus-visible{outline:2px solid #27d3ff;outline-offset:2px}
