/* ===== soft splash: everything eases in; the heart + ECG and the timer arrive after the poster ===== */
@keyframes sbRootIn{from{opacity:0}to{opacity:1}}
@keyframes sbPosterIn{from{opacity:0;transform:scale(1.045)}to{opacity:1;transform:none}}
@keyframes sbSoftIn{from{opacity:0}to{opacity:1}}
#startupSplash{animation:sbRootIn .3s ease-out backwards;transition:opacity .75s cubic-bezier(.4,0,.2,1),visibility .75s linear}
#startupSplash .splash-poster,#startupSplash .splash-wide{animation:sbPosterIn .35s ease-out both;will-change:opacity,transform}
#startupSplash .splash-backdrop{animation:sbSoftIn .3s ease both}
#startupSplash .sp-frame{animation:sbSoftIn .3s ease-out both}
#startupSplash .splash-timer{animation:sbSoftIn .3s ease-out both}
#startupSplash .splash-timer,#startupSplash .splash-timer *{display:none!important;animation:none!important}
@media(prefers-reduced-motion:reduce){#startupSplash,#startupSplash .sp-frame,#startupSplash .splash-timer,#startupSplash .splash-backdrop{animation:none!important;transition:none!important}}
