/* ===== SHBACE HOLOGRAM — independent component (first onboarding page only) =====
   Controls (CSS variables, inherited; set per-element or globally with SHBHolo.set({...})):
   --holo-size   scale of the whole hologram (1 = fits stage width)      --holo-y     vertical offset (px)
   --holo-speed  global animation speed multiplier (1 = normal)          --holo-pulse heartbeat scale amount (0 = none)
   --holo-glow   glow-pulse strength (0-1.5)                             --holo-halo  halo strength (0-1.5)
   --holo-ecg    ECG light-sweep strength (0-1.5)
   Nothing here depends on the four cards, page transitions or swipe state. */
.shb-holo{--holo-size:1;--holo-y:0px;--holo-speed:1;--holo-pulse:.022;--holo-glow:1;--holo-halo:1;--holo-ecg:1;--holo-ratio:1.4944;
 position:absolute;z-index:2;left:50%;top:0;width:calc(var(--holo-w,var(--hw,300px))*var(--holo-size));aspect-ratio:var(--holo-ratio);
 translate:-50% var(--holo-y);pointer-events:none;contain:layout style;transform-origin:50% 0;animation:shbHoloIn .9s cubic-bezier(.2,.8,.3,1) .1s both}
.shb-holo>*{position:absolute;inset:0;width:100%;height:100%;display:block;pointer-events:none}
.shb-holo__img{object-fit:contain;transform-origin:50% 40%;animation:shbHoloBeat calc(.833s/var(--holo-speed)) ease-in-out 1s infinite;will-change:transform}
.shb-holo__glow{object-fit:contain;transform-origin:50% 40%;filter:blur(12px) saturate(1.5) brightness(1.25);mix-blend-mode:screen;opacity:0;
 animation:shbHoloGlow calc(.833s/var(--holo-speed)) ease-in-out 1s infinite;will-change:opacity,transform}
.shb-holo__halo{inset:-10% -6%;width:auto;height:auto;opacity:var(--holo-halo)}
.shb-holo__halo i{position:absolute;inset:0;border-radius:50%;background:radial-gradient(ellipse at 50% 46%,rgba(40,150,255,.34) 0,rgba(30,110,255,.16) 38%,transparent 68%);
 animation:shbHoloHalo calc(3.4s/var(--holo-speed)) ease-in-out infinite;will-change:opacity,transform}
.shb-holo__ecg{overflow:hidden;opacity:var(--holo-ecg);-webkit-mask-image:var(--holo-url);mask-image:var(--holo-url);-webkit-mask-size:100% 100%;mask-size:100% 100%;-webkit-mask-repeat:no-repeat;mask-repeat:no-repeat}
.shb-holo__lit{position:absolute;inset:0;width:100%;height:100%;-webkit-mask-image:url("data:image/webp;base64,"),linear-gradient(180deg,transparent 0,transparent 34%,#000 34%,#000 62%,transparent 62%,transparent 100%);mask-image:url("data:image/webp;base64,"),linear-gradient(180deg,transparent 0,transparent 34%,#000 34%,#000 62%,transparent 62%,transparent 100%);-webkit-mask-size:100% 100%,100% 100%;mask-size:100% 100%,100% 100%;-webkit-mask-repeat:no-repeat;mask-repeat:no-repeat}
/* v15: the light wave used to be a 34%-62% strip (ECG band only). It now spans the full height; .shb-holo__lit limits it to (ECG band) U (whole heart silhouette), so the ECG lighting is unchanged and the complete heart is lit by the SAME wave/animation. */
.shb-holo__ecg i{position:absolute;top:0;height:100%;left:0;width:34%;background:linear-gradient(90deg,transparent,rgba(120,235,255,.0) 8%,rgba(190,250,255,.95) 50%,rgba(120,235,255,0) 92%,transparent);
 mix-blend-mode:screen;transform:translateX(-110%);animation:shbHoloEcg calc(3.2s/var(--holo-speed)) cubic-bezier(.4,.1,.6,.9) 1.2s infinite;will-change:transform}
