/* Daily fact lightbulb: no boxed look. Feathered edges, soft amber glow with a faint blue halo, slow gentle pulse. */
.h7-fact .h7-bulb-wrap{overflow:visible!important;background:none!important;border:0!important;box-shadow:none!important;border-radius:0!important}
.h7-fact .h7-bulb-wrap .h7-bulb{border:0!important;border-radius:0!important;box-shadow:none!important;background:none!important;-webkit-mask-image:radial-gradient(ellipse 50% 50% at 50% 50%,#000 68%,transparent 100%);mask-image:radial-gradient(ellipse 50% 50% at 50% 50%,#000 68%,transparent 100%);animation:h7bulbPulse 5s ease-in-out infinite!important;opacity:1!important;filter:drop-shadow(0 0 8px rgba(255,190,70,.5)) drop-shadow(0 0 18px rgba(255,160,40,.22)) drop-shadow(0 0 30px rgba(70,160,255,.14))!important}
.h7-fact .h7-bulb-wrap:before{animation:h7bulbHalo 5s ease-in-out infinite}
@keyframes h7bulbPulse{0%,100%{filter:drop-shadow(0 0 8px rgba(255,190,70,.5)) drop-shadow(0 0 18px rgba(255,160,40,.22)) drop-shadow(0 0 30px rgba(70,160,255,.14))}50%{filter:drop-shadow(0 0 12px rgba(255,200,90,.78)) drop-shadow(0 0 26px rgba(255,165,45,.36)) drop-shadow(0 0 38px rgba(70,160,255,.22))}}
@keyframes h7bulbHalo{0%,100%{opacity:.75;transform:scale(1)}50%{opacity:1;transform:scale(1.06)}}
@media(prefers-reduced-motion:reduce){.h7-fact .h7-bulb-wrap .h7-bulb,.h7-fact .h7-bulb-wrap:before{animation:none!important}}
.gr-hero{display:flex;align-items:center;gap:16px;padding:16px;border:1px solid rgba(94,182,255,.4);background:linear-gradient(160deg,rgba(18,46,110,.55),rgba(8,22,56,.7));box-shadow:0 0 22px rgba(60,160,255,.18)}
.gr-ring{position:relative;width:92px;height:92px;flex:none}.gr-ring svg{width:100%;height:100%;transform:rotate(-90deg)}
.gr-track{fill:none;stroke:rgba(120,170,230,.2);stroke-width:8}.gr-arc{fill:none;stroke-width:8;stroke-linecap:round}
.gr-ring b{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:20px;color:#eaf4ff}
.gr-tx h3{margin:2px 0 4px;font-size:22px}.gr-note{text-align:center;margin:10px 4px 0}
.phone.light .gr-hero{background:linear-gradient(145deg,#f1f6fc,#fff);border-color:#c9daf1;box-shadow:none}
.phone.light .gr-ring b{color:#1c3f72}.phone.light .gr-track{stroke:#dbe6f3}


/* v47 · splash: nothing is painted until poster + heart are decoded, then ONE layer fades in (no lone heart, no scale mismatch) */
html:has(#startupSplash){background:#030b16}
#startupSplash:not(.sp-ready)>*{opacity:0!important}
#startupSplash>*{transition:opacity .4s ease}
#startupSplash.sp-ready>*{opacity:1}
#startupSplash .splash-poster{animation:none!important}
/* v47 · grade stage: never shrunk by flex / min-height; JS sizes it */
#gradeStage.gx{min-height:0!important;flex:0 0 auto}
